    private function tenant(Request $r): int { return (int) $r->user()->tenant_id; }
    private function owned(string $model, Request $r, int $id) { return $model::where('tenant_id', $this->tenant($r))->findOrFail($id); }
    private function activity(Request $r,string $type,string $subjectType,int $subjectId,string $title,?string $description=null,array $links=[]): void { SalesActivity::create(['tenant_id'=>$this->tenant($r),'user_id'=>$r->user()->id,'activity_type'=>$type,'subject_type'=>$subjectType,'subject_id'=>$subjectId,'contact_id'=>$links['contact_id']??null,'business_id'=>$links['business_id']??null,'opportunity_id'=>$links['opportunity_id']??null,'title'=>$title,'description'=>$description,'metadata'=>$links['metadata']??null,'occurred_at'=>now()]); }

    private function ensurePipeline(int $tenantId): SalesPipeline
    {
        $pipeline = SalesPipeline::firstOrCreate(['tenant_id'=>$tenantId,'is_default'=>true], ['name'=>'Sales Pipeline','description'=>'Default sales process','is_active'=>true]);
        if ($pipeline->stages()->count() === 0) foreach ([['New Lead','#64748b',10],['Qualified','#2563eb',30],['Proposal','#7c3aed',60],['Negotiation','#d97706',80],['Won','#16a34a',100,true,false],['Lost','#dc2626',0,false,true]] as $position=>$stage) PipelineStage::create(['tenant_id'=>$tenantId,'pipeline_id'=>$pipeline->id,'name'=>$stage[0],'color'=>$stage[1],'probability'=>$stage[2],'position'=>$position,'is_won'=>$stage[3]??false,'is_lost'=>$stage[4]??false]);
        return $pipeline;
    }

    public function bootstrap(Request $r)
    {
        $tenantId=$this->tenant($r); $this->ensurePipeline($tenantId);
        $pipelines=SalesPipeline::where('tenant_id',$tenantId)->with(['stages'=>fn($q)=>$q->orderBy('position')])->orderByDesc('is_default')->get();
        $open=Opportunity::where('tenant_id',$tenantId)->where('status','open');
        return response()->json(['pipelines'=>$pipelines,'summary'=>['open_count'=>(clone $open)->count(),'open_value'=>(float)(clone $open)->sum('value'),'won_value'=>(float)Opportunity::where('tenant_id',$tenantId)->where('status','won')->sum('value'),'overdue_tasks'=>CrmTask::where('tenant_id',$tenantId)->whereNotIn('status',['completed','cancelled'])->where('due_at','<',now())->count(),'upcoming_appointments'=>Appointment::where('tenant_id',$tenantId)->where('starts_at','>=',now())->where('starts_at','<=',now()->addDays(7))->where('status','scheduled')->count()],'users'=>User::where('tenant_id',$tenantId)->select('id','name','email')->orderBy('name')->get(),'contacts'=>Contact::where('tenant_id',$tenantId)->select('id','name','email','phone','business_id')->orderBy('name')->limit(500)->get(),'companies'=>Business::where('tenant_id',$tenantId)->select('id','business_name','email','phone')->orderBy('business_name')->limit(500)->get(),'opportunities'=>Opportunity::where('tenant_id',$tenantId)->select('id','name','business_id','contact_id')->latest()->limit(500)->get(),'list_views'=>ListView::where('tenant_id',$tenantId)->where(fn($q)=>$q->whereNull('user_id')->orWhere('user_id',$r->user()->id))->get(),'currency'=>$r->user()->tenant?->currency_code??'USD','timezone'=>$r->user()->tenant?->timezone??'UTC']);
    }

    public function overview(Request $r)
    {
        $tenantId=$this->tenant($r);$pipeline=$r->filled('pipeline_id')?$this->owned(SalesPipeline::class,$r,(int)$r->pipeline_id):$this->ensurePipeline($tenantId);
        $open=Opportunity::where('tenant_id',$tenantId)->where('status','open');$closed=Opportunity::where('tenant_id',$tenantId)->whereIn('status',['won','lost']);$won=(clone $closed)->where('status','won');
        $distribution=PipelineStage::where('tenant_id',$tenantId)->where('pipeline_id',$pipeline->id)->withCount(['opportunities as opportunity_count'=>fn($q)=>$q->where('status','open')])->withSum(['opportunities as stage_value'=>fn($q)=>$q->where('status','open')],'value')->orderBy('position')->get(['id','name','color','probability']);
        $months=collect(range(5,0))->map(function($offset)use($tenantId){$start=now()->startOfMonth()->subMonths($offset);$end=$start->copy()->endOfMonth();return ['month'=>$start->format('M Y'),'won_value'=>(float)Opportunity::where('tenant_id',$tenantId)->where('status','won')->whereBetween('closed_at',[$start,$end])->sum('value'),'won_count'=>Opportunity::where('tenant_id',$tenantId)->where('status','won')->whereBetween('closed_at',[$start,$end])->count()];});
        $activities=SalesActivity::where('tenant_id',$tenantId)->with('user:id,name')->latest('occurred_at')->limit(12)->get();
        $followUps=Opportunity::where('tenant_id',$tenantId)->where('status','open')->with(['stage:id,name,color','contact:id,name','company:id,business_name','owner:id,name'])->where(fn($q)=>$q->whereNull('next_activity_at')->orWhere('next_activity_at','<=',now()))->orderByRaw('next_activity_at IS NULL')->orderBy('next_activity_at')->limit(10)->get();
        $closedCount=(clone $closed)->count();$wonCount=(clone $won)->count();
        return response()->json(['kpis'=>['open_count'=>(clone $open)->count(),'pipeline_value'=>(float)(clone $open)->sum('value'),'won_revenue'=>(float)(clone $won)->sum('value'),'overdue_tasks'=>CrmTask::where('tenant_id',$tenantId)->whereNotIn('status',['completed','cancelled'])->where('due_at','<',now())->count(),'upcoming_appointments'=>Appointment::where('tenant_id',$tenantId)->whereIn('status',['scheduled','confirmed'])->whereBetween('starts_at',[now(),now()->addDays(7)])->count(),'follow_up_count'=>$followUps->count(),'win_rate'=>$closedCount?round(($wonCount/$closedCount)*100,1):0],'pipeline'=>['id'=>$pipeline->id,'name'=>$pipeline->name,'distribution'=>$distribution],'performance'=>$months,'recent_activities'=>$activities,'follow_ups'=>$followUps]);
    }

    public function opportunities(Request $r)
    {
        $q=Opportunity::where('tenant_id',$this->tenant($r))->with(['pipeline:id,name','stage:id,name,color,probability','contact:id,name,email,phone','company:id,business_name','owner:id,name'])->with(['tasks'=>fn($x)=>$x->whereNotIn('status',['completed','cancelled'])->orderBy('due_at')->limit(1)]);
        if($r->filled('pipeline_id'))$q->where('pipeline_id',$r->pipeline_id);if($r->filled('stage_id'))$q->where('stage_id',$r->stage_id);if($r->filled('status'))$q->where('status',$r->status);if($r->filled('owner_id'))$q->where('owner_id',$r->owner_id);if($r->filled('search')){$s=$r->search;$q->where(fn($x)=>$x->where('name','like',"%{$s}%")->orWhereHas('contact',fn($c)=>$c->where('name','like',"%{$s}%"))->orWhereHas('company',fn($c)=>$c->where('business_name','like',"%{$s}%")));}
