    public function opportunity(Request $r,int $opportunity)
    {
        $op=$this->owned(Opportunity::class,$r,$opportunity)->load(['pipeline','stage','contact','company','owner:id,name,email','tasks.owner:id,name','appointments.owner:id,name','activities.user:id,name']);
        $customFields=CustomField::where('tenant_id',$this->tenant($r))->where('entity_type','opportunity')->where('is_active',true)->orderBy('position')->get();$values=CustomFieldValue::where('tenant_id',$this->tenant($r))->where('entity_type','opportunity')->where('entity_id',$op->id)->get()->keyBy('custom_field_id');
