    public function savePipeline(Request $r, AuditService $audit)
    {
        $data=$r->validate(['id'=>'nullable|integer','name'=>'required|string|max:120','description'=>'nullable|string|max:1000','is_default'=>'boolean','is_active'=>'boolean']); $tenantId=$this->tenant($r);
