        if(!empty($data['is_default'])) SalesPipeline::where('tenant_id',$tenantId)->update(['is_default'=>false]); $pipeline->fill($data)->save(); if($pipeline->stages()->count()===0) foreach(['New Lead','Qualified','Proposal','Won','Lost'] as $i=>$name) PipelineStage::create(['tenant_id'=>$tenantId,'pipeline_id'=>$pipeline->id,'name'=>$name,'position'=>$i,'probability'=>$i===3?100:($i===4?0:$i*25),'is_won'=>$name==='Won','is_lost'=>$name==='Lost']);
        $audit->record($tenantId,'sales',$pipeline->wasRecentlyCreated?'pipeline.created':'pipeline.updated',$pipeline,[],[],$pipeline->name); return response()->json(['message'=>'Pipeline saved','pipeline'=>$pipeline->load('stages')]);
    }

    public function deletePipeline(Request $r,int $pipeline)
    {
        $record=$this->owned(SalesPipeline::class,$r,$pipeline); if($record->is_default||$record->opportunities()->exists()) return response()->json(['message'=>'Default or non-empty pipelines cannot be deleted. Move their opportunities first.'],422); $record->stages()->delete();$record->delete();return response()->json(['message'=>'Pipeline deleted']);
    }

