        if($record->opportunities()->exists()){if(!$replacement||$replacement===$record->id)return response()->json(['message'=>'Choose a different replacement stage before deleting a stage that contains opportunities.'],422);$target=PipelineStage::where('tenant_id',$this->tenant($r))->where('pipeline_id',$record->pipeline_id)->where('id','!=',$record->id)->findOrFail($replacement);$record->opportunities()->update(['stage_id'=>$target->id]);}
