    public function configuration(Request $r)
    {
        $t=$this->tenant($r);return response()->json(['custom_fields'=>CustomField::where('tenant_id',$t)->orderBy('entity_type')->orderBy('position')->get(),'saved_lists'=>SavedContactList::where('tenant_id',$t)->latest()->get(),'list_views'=>ListView::where('tenant_id',$t)->where(fn($q)=>$q->whereNull('user_id')->orWhere('user_id',$r->user()->id))->get(),'imports'=>ContactImportRun::where('tenant_id',$t)->with('user:id,name')->latest()->limit(50)->get(),'tag_categories'=>TagCategory::where('tenant_id',$t)->withCount('tags')->get(),'tags'=>Tag::where(fn($q)=>$q->where('tenant_id',$t)->orWhereNull('tenant_id'))->with('category')->withCount('contacts')->get(),'value_folders'=>CustomValueFolder::where('tenant_id',$t)->with('values')->get(),'reusable_values'=>CustomValue::where('tenant_id',$t)->with('folder')->orderBy('name')->get()]);
    }

    public function saveCustomField(Request $r)
    {
        $t=$this->tenant($r);$data=$r->validate(['id'=>'nullable|integer','entity_type'=>'required|in:contact,opportunity,company','key'=>'required|string|max:80','name'=>'required|string|max:120','field_type'=>'required|in:text,textarea,number,date,boolean,select,multi_select,email,url','options'=>'nullable|array','validation'=>'nullable|array','is_required'=>'boolean','is_active'=>'boolean','position'=>'integer|min:0']);$field=isset($data['id'])?$this->owned(CustomField::class,$r,(int)$data['id']):new CustomField(['tenant_id'=>$t]);if($field->exists)unset($data['key'],$data['entity_type']);else$data['key']=str()->slug($data['key'],'_');$field->fill($data)->save();return response()->json(['message'=>'Custom field saved','field'=>$field]);
    }
    public function deleteCustomField(Request $r,int $field){$f=$this->owned(CustomField::class,$r,$field);if(CustomFieldValue::where('custom_field_id',$f->id)->exists())return response()->json(['message'=>'This field contains data. Disable it instead of deleting it.'],422);$f->delete();return response()->json(['message'=>'Custom field deleted']);}
    public function entityCustomValues(Request $r,string $type,int $id){$this->assertCustomEntity($r,$type,$id);return response()->json(CustomFieldValue::where('tenant_id',$this->tenant($r))->where('entity_type',$type)->where('entity_id',$id)->get()->keyBy('custom_field_id'));}
    public function saveEntityCustomValues(Request $r,string $type,int $id){$this->assertCustomEntity($r,$type,$id);$values=$r->validate(['values'=>'required|array'])['values'];$fields=CustomField::where('tenant_id',$this->tenant($r))->where('entity_type',$type)->where('is_active',true)->get()->keyBy('id');foreach($fields as $field){$value=$values[$field->id]??null;if($field->is_required&&($value===null||$value===''))return response()->json(['message'=>"{$field->name} is required.",'errors'=>["values.{$field->id}"=>['This custom field is required.']]],422);if(array_key_exists($field->id,$values))CustomFieldValue::updateOrCreate(['tenant_id'=>$this->tenant($r),'custom_field_id'=>$field->id,'entity_type'=>$type,'entity_id'=>$id],['value'=>is_array($value)?$value:['value'=>$value]]);}return response()->json(['message'=>'Custom fields saved']);}
    private function assertCustomEntity(Request $r,string $type,int $id): void { $models=['contact'=>Contact::class,'opportunity'=>Opportunity::class,'company'=>Business::class];abort_unless(isset($models[$type]),404);$models[$type]::where('tenant_id',$this->tenant($r))->findOrFail($id); }

    public function saveList(Request $r){$data=$r->validate(['id'=>'nullable|integer','name'=>'required|string|max:120','description'=>'nullable|string','filters'=>'required|array','is_shared'=>'boolean']);$list=isset($data['id'])?$this->owned(SavedContactList::class,$r,(int)$data['id']):new SavedContactList(['tenant_id'=>$this->tenant($r),'user_id'=>$r->user()->id]);$list->fill($data)->save();return response()->json(['message'=>'Dynamic list saved','list'=>$list]);}
    public function listMembers(Request $r,int $list){$record=$this->owned(SavedContactList::class,$r,$list);$q=Contact::where('tenant_id',$this->tenant($r));$f=$record->filters;if(!empty($f['status']))$q->where('status',$f['status']);if(!empty($f['company']))$q->where('company','like','%'.$f['company'].'%');if(!empty($f['tag_id']))$q->whereHas('tags',fn($x)=>$x->where('tags.id',$f['tag_id']));if(!empty($f['category_id']))$q->whereHas('categories',fn($x)=>$x->where('categories.id',$f['category_id']));if(($f['has_email']??null)===true)$q->whereNotNull('email');if(!empty($f['search'])){$s=$f['search'];$q->where(fn($x)=>$x->where('name','like',"%{$s}%")->orWhere('email','like',"%{$s}%"));}return response()->json($q->paginate(50));}
    public function deleteList(Request $r,int $list){$this->owned(SavedContactList::class,$r,$list)->delete();return response()->json(['message'=>'List deleted']);}
    public function saveView(Request $r){$data=$r->validate(['id'=>'nullable|integer','entity_type'=>'required|in:contacts,opportunities,tasks,companies','name'=>'required|string|max:120','columns'=>'required|array','columns.*'=>'string|max:80','sorts'=>'nullable|array','filters'=>'nullable|array','is_default'=>'boolean']);if(!empty($data['is_default']))ListView::where('tenant_id',$this->tenant($r))->where('user_id',$r->user()->id)->where('entity_type',$data['entity_type'])->update(['is_default'=>false]);$view=isset($data['id'])?$this->owned(ListView::class,$r,(int)$data['id']):new ListView(['tenant_id'=>$this->tenant($r),'user_id'=>$r->user()->id]);$view->fill($data)->save();return response()->json(['message'=>'List view saved','view'=>$view]);}
    public function deleteView(Request $r,int $view){$this->owned(ListView::class,$r,$view)->delete();return response()->json(['message'=>'View deleted']);}

    public function saveTagCategory(Request $r){$data=$r->validate(['id'=>'nullable|integer','name'=>'required|string|max:120','description'=>'nullable|string','color'=>'nullable|string|max:20']);$c=isset($data['id'])?$this->owned(TagCategory::class,$r,(int)$data['id']):new TagCategory(['tenant_id'=>$this->tenant($r)]);$c->fill($data)->save();return response()->json(['message'=>'Tag category saved','category'=>$c]);}
    public function deleteTagCategory(Request $r,int $category){$c=$this->owned(TagCategory::class,$r,$category);$c->tags()->update(['tag_category_id'=>null]);$c->delete();return response()->json(['message'=>'Tag category deleted; tags were retained']);}
    public function saveFolder(Request $r){$data=$r->validate(['id'=>'nullable|integer','name'=>'required|string|max:120','description'=>'nullable|string']);$f=isset($data['id'])?$this->owned(CustomValueFolder::class,$r,(int)$data['id']):new CustomValueFolder(['tenant_id'=>$this->tenant($r)]);$f->fill($data)->save();return response()->json(['message'=>'Folder saved','folder'=>$f]);}
    public function saveReusableValue(Request $r){$t=$this->tenant($r);$data=$r->validate(['id'=>'nullable|integer','folder_id'=>['nullable',Rule::exists('custom_value_folders','id')->where('tenant_id',$t)],'key'=>'required|string|max:100','name'=>'required|string|max:120','value'=>'required|string','value_type'=>'required|in:text,url,email,number','is_active'=>'boolean']);$v=isset($data['id'])?$this->owned(CustomValue::class,$r,(int)$data['id']):new CustomValue(['tenant_id'=>$t]);if($v->exists)unset($data['key']);else$data['key']=str()->slug($data['key'],'_');$v->fill($data)->save();return response()->json(['message'=>'Reusable value saved','value'=>$v]);}
    public function deleteReusableValue(Request $r,int $value){$v=$this->owned(CustomValue::class,$r,$value);if($v->usage_count>0)return response()->json(['message'=>'This value is in use. Disable it instead of deleting it.'],422);$v->delete();return response()->json(['message'=>'Reusable value deleted']);}
}
